{
  "summary": "To get ready for a BTO launch next year, you should start the HFE application, gather required documents, and ensure you meet the basic eligibility criteria.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "First-timer couples must obtain an HFE (Housing Flat Eligibility) letter before they can apply for a BTO flat."
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Log in to the HDB Flat Portal and start the HFE application as soon as possible, as processing can take several weeks."
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Prepare the required documents for the HFE application, including NRICs, latest CPF contribution statements, recent payslips, and income tax notices for both applicants."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Check that both applicants are Singapore Citizens and have not previously owned any HDB flat or received any housing subsidy, as this is a key eligibility condition for first-timer couples."
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Confirm that neither of you holds any private residential property in Singapore or overseas, as ownership of private property can affect HFE eligibility."
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "If you are planning to have children or are expecting, note that this does not affect HFE eligibility but may be relevant for future grant considerations."
    },
    {
      "claim_id": "c7",
      "kind": "caveat",
      "text": "Policy details such as processing times and document requirements can change; always verify the latest information on the official HDB website (hdb.gov.sg) or the HDB Flat Portal."
    }
  ],
  "missing_profile_fields": [
    {
      "field": "hfe_status",
      "follow_up_question": "Have you already submitted the HFE application, or is it still pending?"
    },
    {
      "field": "private_property_interest",
      "follow_up_question": "Do either of you currently own or have an interest in any private residential property in Singapore or abroad?"
    },
    {
      "field": "children_or_expecting",
      "follow_up_question": "Do you have any children or are you expecting a child in the near future?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
